import { URL } from "node:url";
import console from "node:console";
import process from "node:process";
import { readFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";
import { format } from "prettier";
const generated = await format(
  "/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n" +
    astToString(
      await openapiTS(
        new URL("../../contracts/v1/openapi.json", import.meta.url),
      ),
    ),
  { parser: "typescript" },
);
const committed = await readFile(
  new URL("../src/api/contracts.generated.ts", import.meta.url),
  "utf8",
);
if (generated !== committed) {
  console.error("Contract types drifted. Run pnpm contracts:generate.");
  process.exitCode = 1;
}
